'use strict'

// Generated by vfs_scaffold_auth. PostgreSQL storage for app users, roles, sessions and invites (driver: pg).
// Connection: DATABASE_URL, or the standard PG* variables (both injected by the preview).

const fs = require('node:fs')
const path = require('node:path')
const { Pool } = require('pg')
const config = require('./config')

const pool = new Pool(process.env.DATABASE_URL ? { connectionString: process.env.DATABASE_URL, max: 5 } : { max: 5 })
// Serialises sign-ups and admin changes, so "first user becomes admin" and "keep one admin" hold under concurrency.
const LOCK_KEY = 727_001
const SWEEP_EVERY_MS = 60 * 60 * 1000
let lastSweep = 0
let readyPromise = null

const toUser = (row, roles = []) => ({
  id: Number(row.id),
  email: row.email,
  name: row.name,
  disabled: Boolean(row.disabled),
  createdAt: row.created_at ? new Date(row.created_at).toISOString() : null,
  roles,
})

async function transaction(work) {
  const client = await pool.connect()
  try {
    await client.query('BEGIN')
    await client.query('SELECT pg_advisory_xact_lock($1)', [LOCK_KEY])
    const result = await work(client)
    await client.query(result && result.error ? 'ROLLBACK' : 'COMMIT')
    return result
  } catch (error) {
    await client.query('ROLLBACK').catch(() => {})
    throw error
  } finally {
    client.release()
  }
}

async function rolesOf(db, userIds) {
  const byUser = new Map(userIds.map((id) => [id, []]))
  if (!userIds.length) return byUser
  const { rows } = await db.query('SELECT user_id, role FROM app_user_roles WHERE user_id = ANY($1::bigint[]) ORDER BY role', [userIds])
  for (const row of rows) byUser.get(Number(row.user_id))?.push(row.role)
  return byUser
}

async function setup() {
  const file = path.join(__dirname, '..', config.schemaFile)
  await transaction(async(client) => {
    if (fs.existsSync(file)) await client.query(fs.readFileSync(file, 'utf8'))
    for (const role of config.roles) await client.query('INSERT INTO app_roles (name) VALUES ($1) ON CONFLICT DO NOTHING', [role])
  })
}

/** Resolves once the tables exist. A failure (database not up yet) is retried on the next call. */
function ready() {
  if (!readyPromise) readyPromise = setup().catch((error) => {
    readyPromise = null
    throw error
  })
  return readyPromise
}

async function countUsers() {
  const { rows } = await pool.query('SELECT count(*)::int AS n FROM app_users')
  return rows[0].n
}

async function getUser(id, db = pool) {
  const { rows } = await db.query('SELECT id, email, name, disabled, created_at FROM app_users WHERE id = $1', [id])
  if (!rows.length) return null
  return toUser(rows[0], (await rolesOf(db, [Number(rows[0].id)])).get(Number(rows[0].id)))
}

async function findUserByEmail(email) {
  const { rows } = await pool.query('SELECT id, email, name, password_hash, disabled FROM app_users WHERE email = $1', [email])
  return rows.length ? { ...toUser(rows[0]), passwordHash: rows[0].password_hash } : null
}

async function listUsers() {
  const { rows } = await pool.query('SELECT id, email, name, disabled, created_at FROM app_users ORDER BY created_at, id')
  const roles = await rolesOf(pool, rows.map((row) => Number(row.id)))
  return rows.map((row) => toUser(row, roles.get(Number(row.id))))
}

async function createUser({ email, name, passwordHash, inviteHash, assignRoles }) {
  return transaction(async(client) => {
    const isFirst = (await client.query('SELECT 1 FROM app_users LIMIT 1')).rows.length === 0
    let invite = null
    if (inviteHash) {
      const { rows } = await client.query(
        'SELECT code_hash, email, roles FROM app_invites WHERE code_hash = $1 AND used_at IS NULL AND expires_at > now()',
        [inviteHash]
      )
      if (rows.length) invite = { email: rows[0].email, roles: JSON.parse(rows[0].roles || '[]') }
    }
    const decision = assignRoles({ isFirst, invite })
    if (decision.error) return { error: decision.error }
    if ((await client.query('SELECT 1 FROM app_users WHERE email = $1', [email])).rows.length) return { error: 'EMAIL_TAKEN' }

    const { rows } = await client.query(
      'INSERT INTO app_users (email, name, password_hash, disabled, created_at) VALUES ($1, $2, $3, FALSE, now()) RETURNING id',
      [email, name, passwordHash]
    )
    const id = Number(rows[0].id)
    for (const role of decision.roles) await client.query('INSERT INTO app_user_roles (user_id, role) VALUES ($1, $2) ON CONFLICT DO NOTHING', [id, role])
    if (invite) await client.query('UPDATE app_invites SET used_at = now() WHERE code_hash = $1', [inviteHash])
    return { user: await getUser(id, client) }
  })
}

async function setPasswordHash(id, passwordHash) {
  await pool.query('UPDATE app_users SET password_hash = $2 WHERE id = $1', [id, passwordHash])
}

async function updateUser(id, { roles, disabled }, adminRole) {
  return transaction(async(client) => {
    if (!(await client.query('SELECT 1 FROM app_users WHERE id = $1', [id])).rows.length) return { error: 'NOT_FOUND' }
    if (disabled !== undefined) await client.query('UPDATE app_users SET disabled = $2 WHERE id = $1', [id, disabled])
    if (roles !== undefined) {
      await client.query('DELETE FROM app_user_roles WHERE user_id = $1', [id])
      for (const role of roles) await client.query('INSERT INTO app_user_roles (user_id, role) VALUES ($1, $2)', [id, role])
    }
    const { rows } = await client.query(
      'SELECT count(*)::int AS n FROM app_users u JOIN app_user_roles r ON r.user_id = u.id WHERE r.role = $1 AND NOT u.disabled',
      [adminRole]
    )
    if (rows[0].n === 0) return { error: 'LAST_ADMIN' }
    return { user: await getUser(id, client) }
  })
}

async function createSession({ id, userId, expiresAt, createdAt }) {
  if (Date.now() - lastSweep > SWEEP_EVERY_MS) {
    lastSweep = Date.now()
    await pool.query('DELETE FROM app_sessions WHERE expires_at < now()')
  }
  await pool.query('INSERT INTO app_sessions (id, user_id, expires_at, created_at) VALUES ($1, $2, $3, $4)', [id, userId, expiresAt, createdAt])
}

async function findSession(id) {
  const { rows } = await pool.query('SELECT user_id, expires_at FROM app_sessions WHERE id = $1', [id])
  return rows.length ? { userId: Number(rows[0].user_id), expiresAt: new Date(rows[0].expires_at).toISOString() } : null
}

async function touchSession(id, expiresAt) {
  await pool.query('UPDATE app_sessions SET expires_at = $2 WHERE id = $1', [id, expiresAt])
}

async function deleteSession(id) {
  await pool.query('DELETE FROM app_sessions WHERE id = $1', [id])
}

async function deleteUserSessions(userId) {
  await pool.query('DELETE FROM app_sessions WHERE user_id = $1', [userId])
}

async function createInvite({ codeHash, email, roles, createdBy, expiresAt }) {
  await pool.query(
    'INSERT INTO app_invites (code_hash, email, roles, created_by, expires_at, created_at) VALUES ($1, $2, $3, $4, $5, now())',
    [codeHash, email, JSON.stringify(roles), createdBy, expiresAt]
  )
}

const close = () => pool.end()

module.exports = {
  engine: 'postgres', ready, countUsers, getUser, findUserByEmail, listUsers, createUser, setPasswordHash, updateUser,
  createSession, findSession, touchSession, deleteSession, deleteUserSessions, createInvite, close,
}
